# run-all-tests.ps1 – 一键自动化执行所有测试\r\n\r\n# 1️⃣ 确保依赖已安装（若已装可略过）\r\nWrite-Host "🔧 正在安装依赖..."\r\nnpm install\r\n\r\n# 2️⃣ 初始化 SQLite 数据库（创建表结构）\r\nWrite-Host "🗄️ 初始化 SQLite 数据库..."\r\nnode -e "import('./server/db.js').then(m=>m.initDB())"\r\n\r\n# 3️⃣ 运行后端 Vitest 单元/集成测试（已排除 e2e）\r\nWrite-Host "⚙️ 正在运行 Vitest 单元测试..."\r\nnpm run test\r\n\r\n# 4️⃣ 运行前端 Playwright UI 自动化测试\r\nWrite-Host "🧪 正在运行 Playwright E2E 测试..."\r\nnpm run test:e2e\r\n\r\nWrite-Host "✅ 所有步骤已完成！"
